    public void handleOrders(Client client, Object message)
    {
        //
        //    {
        //        "type": "myOrder",
        //        "code": "KRW-BTC",
        //        "uuid": "C0101000000001818113",
        //        "ask_bid": "BID",
        //        "order_type": "limit",
        //        "state": "trade",
        //        "trade_uuid": "C0101000000001744207",
        //        "price": 1927000,
        //        "volume": 0.4697,
        //        "remaining_volume": 0.0803,
        //        "executed_volume": 0.4697,
        //        "trades_count": 1,
        //        "reserved_fee": 0,
        //        "remaining_fee": 0,
        //        "paid_fee": 0,
        //        "executed_funds": 905111.9000,
        //        "trade_timestamp": 1727052318148,
        //        "order_timestamp": 1727052318074,
        //        "timestamp": 1727052318369,
        //        "stream_type": "REALTIME"
        //    }
        //
        Object messageHash = "myOrder";
        Object parsed = this.parseWsOrder(message);
        Object symbol = this.safeString(parsed, "symbol");
        // const orderId = this.safeString (parsed, 'id');
        if (Helpers.isTrue(Helpers.isEqual(this.orders, null)))
        {
            Object limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        Object cachedOrders = this.orders;
        Helpers.callDynamically(cachedOrders, "append", new Object[]{parsed});
        client.resolve(cachedOrders, messageHash);
        Object symbolSpecificMessageHash = Helpers.add(Helpers.add(messageHash, ":"), symbol);
        client.resolve(cachedOrders, symbolSpecificMessageHash);
    }

    public Object parseWsOrder(Object order, Object... optionalArgs)
    {
        //
        //    {
        //        "type": "myOrder",
        //        "code": "KRW-BTC",
        //        "uuid": "C0101000000001818113",
        //        "ask_bid": "BID",
        //        "order_type": "limit",
        //        "state": "trade",
        //        "trade_uuid": "C0101000000001744207",
        //        "price": 1927000,
        //        "volume": 0.4697,
        //        "remaining_volume": 0.0803,
        //        "executed_volume": 0.4697,
        //        "trades_count": 1,
        //        "reserved_fee": 0,
        //        "remaining_fee": 0,
        //        "paid_fee": 0,
        //        "executed_funds": 905111.9000,
        //        "trade_timestamp": 1727052318148,
        //        "order_timestamp": 1727052318074,
        //        "timestamp": 1727052318369,
        //        "stream_type": "REALTIME"
        //    }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(order, "code");
        Object symbol = this.safeSymbol(marketId, market, "-");
        Object timestamp = this.safeInteger(order, "order_timestamp");
        Object sideId = this.safeString(order, "ask_bid");
        Object side = ((Helpers.isTrue((Helpers.isEqual(sideId, "BID"))))) ? ("buy") : ("sell");
        Object typeId = this.safeString(order, "order_type");
        Object type = null;
        if (Helpers.isTrue(Helpers.isEqual(typeId, "limit")))
        {
            type = "limit";
        } else if (Helpers.isTrue(Helpers.isEqual(typeId, "price")))
        {
            type = "market";
        } else if (Helpers.isTrue(Helpers.isEqual(typeId, "market")))
        {
            type = "market";
        }
        Object stateId = this.safeString(order, "state");
        Object status = null;
        if (Helpers.isTrue(Helpers.isEqual(stateId, "wait")))
        {
            status = "open";
        } else if (Helpers.isTrue(Helpers.isEqual(stateId, "trade")))
        {
            status = "open";
        } else if (Helpers.isTrue(Helpers.isEqual(stateId, "done")))
        {
            status = "closed";
        } else if (Helpers.isTrue(Helpers.isEqual(stateId, "cancel")))
        {
            status = "canceled";
        }
        Object price = this.safeString(order, "price");
        Object amount = this.safeString(order, "volume");
        Object remaining = this.safeString(order, "remaining_volume");
        Object filled = this.safeString(order, "executed_volume");
        Object cost = this.safeString(order, "executed_funds");
        Object feeCost = this.safeString(order, "paid_fee");
        Object fee = null;
        if (Helpers.isTrue(!Helpers.isEqual(feeCost, null)))
        {
            Object marketForFee = this.safeMarket(marketId, market);
            Object feeCurrency = this.safeString(marketForFee, "quote");
            final Object finalFeeCost = feeCost;
            fee = new java.util.HashMap<String, Object>() {{
                put( "cost", finalFeeCost );
                put( "currency", feeCurrency );
            }};
        }
        final Object finalType = type;
        final Object finalStatus = status;
        final Object finalFee = fee;
        return this.safeOrder(new java.util.HashMap<String, Object>() {{
            put( "info", order );
            put( "id", Bithumb.this.safeString(order, "uuid") );
            put( "clientOrderId", null );
            put( "timestamp", timestamp );
            put( "datetime", Bithumb.this.iso8601(timestamp) );
            put( "lastTradeTimestamp", Bithumb.this.safeInteger(order, "trade_timestamp") );
            put( "symbol", symbol );
            put( "type", finalType );
            put( "timeInForce", null );
            put( "postOnly", null );
            put( "side", side );
            put( "price", price );
            put( "stopPrice", null );
            put( "triggerPrice", null );
            put( "amount", amount );
            put( "cost", cost );
            put( "average", null );
            put( "filled", filled );
            put( "remaining", remaining );
            put( "status", finalStatus );
            put( "fee", finalFee );
            put( "trades", null );
        }}, market);
    }

    public void handleMessage(Client client, Object message)
    {
        if (Helpers.isTrue(!Helpers.isEqual(this.handleErrorMessage(client, message), true)))
        {
            return;
        }
        Object topic = this.safeString(message, "type");
        if (Helpers.isTrue(!Helpers.isEqual(topic, null)))
        {
            Object methods = new java.util.HashMap<String, Object>() {{
                put( "ticker", "handleTicker");
                put( "orderbookdepth", "handleOrderBook");
                put( "transaction", "handleTrades");
                put( "myAsset", "handleBalance");
                put( "myOrder", "handleOrders");
            }};
            Object method = this.safeValue(methods, topic);
            if (Helpers.isTrue(!Helpers.isEqual(method, null)))
            {
                Helpers.callDynamically(this, method, new Object[] {client, message});
            }
        }
    }
